import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-08-08 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-08-08 -- Ceph Performance Meeting","date":"2019-08-08T00:00:00.000Z","updated":"2019-08-12T00:00:00.000Z","tags":["Ceph性能","存储优化","分布式存储","Alec尺寸调整","Blue Store"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-08_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-08-08_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-08-08_-_-_Ceph_Performance_Meeting.md"};function n(s,l,a,g,p,u){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： 核心团队成员</p><p><strong>会议主题</strong>： 讨论Ceph项目的最新进展、关键性能问题及后续行动计划。</p><p><strong>关键细节</strong>：</p><ul><li><strong>Alec尺寸变更</strong>： <ul><li>由于碎片化导致的空间浪费，团队成员正在讨论将Alec尺寸从64k调整到更大的值，以优化存储效率。</li><li>讨论中提出了两个PR：一个将Alec尺寸设置为64k，另一个在共享设备上使用64k的Alec尺寸，但在Blue Store TV或Well设备上不使用。</li></ul></li><li><strong>异步读取PR</strong>： <ul><li>讨论了一个实现异步读取的OSD PR，但需要进一步的性能和剖析数据来评估其影响。</li></ul></li><li><strong>其他PR</strong>： <ul><li>Jinping的PR：优化了IO通知解锁操作，提高了性能。</li><li>Igor的PR：减少了锁获取的开销。</li><li>Champagne的PR：减少了不必要的通知，可能略微提高了性能。</li><li>Eric的PR：合并了一个小的RG w PR qualms PR，可能没有太大影响，但有助于提高性能。</li></ul></li><li><strong>Blue Store Alexeyes</strong>： <ul><li>Neha的PR：针对Blue Store Alexeyes进行了一些调整。</li><li>Adam的PR：对Boost和元数据进行了研究，并将其组织到不同的列族中。</li><li>讨论了将PG日志信息存储在单独的列族中的利弊，以及如何优化存储和内存缓冲区。</li></ul></li><li><strong>其他议题</strong>： <ul><li>MDS和Mon内存限制的优化。</li><li>自动化Rocks DB文件在BlueFS设备之间移动的PR。</li><li>IOU ring和messenger的PR。</li><li>op tracker PR。</li><li>cash bidding rebase。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>Alec尺寸变更</strong>： <ul><li>讨论了将Alec尺寸从64k调整到更大的值的利弊。</li><li>分析了不同Alec尺寸对性能的影响。</li><li>讨论了是否应该将PG日志信息存储在单独的列族中。</li></ul></li><li><strong>其他议题</strong>： <ul><li>讨论了如何优化存储和内存缓冲区。</li><li>讨论了如何将Rocks DB文件在BlueFS设备之间移动。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续讨论Alec尺寸变更，并收集更多数据。</li><li>对异步读取PR进行进一步的分析。</li><li>对其他PR进行审查和合并。</li><li>继续优化MDS和Mon内存限制。</li><li>完成其他议题的相关工作。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>收集更多数据以评估Alec尺寸变更的影响。</li><li>对异步读取PR进行进一步的分析。</li><li>完成其他PR的审查和合并。</li><li>完成MDS和Mon内存限制的优化。</li><li>完成其他议题的相关工作。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文关键词，例如Alec、Blue Store、RocksDB、OSD、PG、column family等。</li><li>会议中讨论了一些具体的性能测试和实验，例如迭代测试、写入测试等。</li></ul>',14)])])}const P=e(r,[["render",n]]);export{c as __pageData,P as default};
